import subprocess, os
out=subprocess.run(['ps','auxww'],text=True,stdout=subprocess.PIPE).stdout
for line in out.splitlines():
    if 'sed -n' in line or 'xargs' in line or 'afl-compiler' in line or 'cat description' in line:
        print(line)
print('bash procs')
for line in out.splitlines():
    if 'bash' in line or 'sh -c' in line:
        print(line)
